import pytest

from grounding_checker import (
    CheckerConfig,
    run_grounding_checks,
    check_sentence_support,
    check_pair_usefulness,
    check_redundancy,
    content_tokens,
    jaccard_similarity,
    overlap_ratio,
    format_grounding_report,
)
from qra_schema import QRAResult, QRAPair, EvidenceItem, PairType, ActionableFor, Confidence, EvidenceField


def make_pair(
    pair_id: str,
    pair_type: str,
    question: str,
    reasoning: str,
    answer: str,
    evidence: list[dict],
    actionable_for: list[str] | None = None,
    confidence: str = "high",
) -> QRAPair:
    """Helper to build QRAPair."""
    return QRAPair(
        pair_id=pair_id,
        pair_type=PairType(pair_type),
        actionable_for=[ActionableFor(a) for a in (actionable_for or ["vulnerability_assessment"])],
        question=question,
        reasoning=reasoning,
        answer=answer,
        confidence=Confidence(confidence),
        evidence=[
            EvidenceItem(field=EvidenceField(e["field"]), quote=e["quote"])
            for e in evidence
        ],
    )


def make_result(pairs: list[QRAPair]) -> QRAResult:
    """Helper to build QRAResult."""
    return QRAResult(
        source_framework="CWE",
        source_id="CWE-119",
        pair_count=len(pairs),
        abstained=False,
        pairs=pairs,
    )


