class TestBadGrounding:
    """QRA pairs that should fail grounding checks."""

    def test_answer_introduces_unsupported_claims(self):
        """Answer makes claims not in evidence."""
        pair = make_pair(
            pair_id="CWE-119-QRA-1",
            pair_type="risk_context",
            question="Why is CWE-119 dangerous in embedded systems?",
            reasoning="The record mentions memory buffer operations.",
            # This answer introduces "embedded systems", "real-time", "RTOS" - not in evidence
            answer="CWE-119 is particularly dangerous in embedded systems because real-time operating systems often lack memory protection, making buffer overflows easier to exploit in RTOS environments.",
            evidence=[
                {
                    "field": "description",
                    "quote": "The product performs operations on a memory buffer.",
                }
            ],
        )
        result = make_result([pair])
        report = run_grounding_checks(result)

        # Should fail because answer introduces many tokens not in evidence
        assert not report.passed, "Expected failure for unsupported claims"

    def test_reasoning_adds_new_mechanisms(self):
        """Reasoning invents mechanisms not stated in evidence."""
        pair = make_pair(
            pair_id="CWE-119-QRA-1",
            pair_type="scope_clarification",
            question="What mechanisms cause CWE-119 in practice?",
            # Reasoning invents "stack smashing", "heap spraying", "return-oriented programming"
            reasoning="CWE-119 is typically caused by stack smashing attacks, heap spraying techniques, and return-oriented programming exploits that manipulate memory layouts.",
            answer="Buffer overflows occur when memory boundaries are exceeded.",
            evidence=[
                {
                    "field": "description",
                    "quote": "reads from or writes to a memory location outside the buffer's intended boundary",
                }
            ],
        )
        result = make_result([pair])
        report = run_grounding_checks(result)

        # Should flag reasoning as unsupported
        unsupported_reasoning = [
            c for c in report.pair_checks[0].reasoning_checks if not c.supported
        ]
        assert len(unsupported_reasoning) > 0, "Expected unsupported reasoning sentences"

    def test_generic_question_no_cwe_specifics(self):
        """Question and answer are too generic."""
        pair = make_pair(
            pair_id="CWE-119-QRA-1",
            pair_type="risk_context",
            question="What is CWE-119 and why does it matter?",
            reasoning="Security vulnerabilities can cause problems.",
            answer="Security issues can lead to system compromise and data breaches.",
            evidence=[
                {
                    "field": "description",
                    "quote": "memory buffer",
                }
            ],
        )
        result = make_result([pair])
        report = run_grounding_checks(result)

        # Should have usefulness warnings about genericness
        warnings = report.pair_checks[0].usefulness_warnings
        assert any("generic" in w.lower() for w in warnings), f"Expected genericness warning, got: {warnings}"


