class TestRedundancy:
    """Test redundancy detection between pairs."""

    def test_near_duplicate_questions_flagged(self):
        """Two questions that are paraphrases should be flagged."""
        pair1 = make_pair(
            pair_id="CWE-119-QRA-1",
            pair_type="scope_clarification",
            question="What memory operations does CWE-119 cover?",
            reasoning="The description defines memory buffer operations.",
            answer="CWE-119 covers read and write operations on memory buffers.",
            evidence=[{"field": "description", "quote": "operations on a memory buffer"}],
        )
        pair2 = make_pair(
            pair_id="CWE-119-QRA-2",
            pair_type="scope_clarification",
            question="Which memory operations are covered by CWE-119?",
            reasoning="The weakness involves memory buffer operations.",
            answer="CWE-119 involves read and write operations on memory buffers.",
            evidence=[{"field": "description", "quote": "operations on a memory buffer"}],
        )
        result = make_result([pair1, pair2])
        report = run_grounding_checks(result)

        # Should flag redundancy
        flagged = [r for r in report.redundancy_checks if r.flagged]
        assert len(flagged) > 0, "Expected redundancy flag for near-duplicate questions"

    def test_distinct_pairs_not_flagged(self):
        """Two genuinely different pairs should not be flagged."""
        pair1 = make_pair(
            pair_id="CWE-119-QRA-1",
            pair_type="scope_clarification",
            question="What memory operations does CWE-119 cover?",
            reasoning="The description defines memory buffer operations.",
            answer="CWE-119 covers read and write operations on memory buffers.",
            evidence=[{"field": "description", "quote": "operations on a memory buffer"}],
        )
        pair2 = make_pair(
            pair_id="CWE-119-QRA-2",
            pair_type="implementation_guidance",
            question="How should developers prevent CWE-119 vulnerabilities?",
            reasoning="The mitigations recommend using safe languages and bounded functions.",
            answer="Developers should use memory-safe languages and replace unbounded copy functions with strncpy.",
            actionable_for=["implementation"],
            evidence=[{"field": "potential_mitigations", "quote": "Replace unbounded copy functions with analogous functions that support length arguments"}],
        )
        result = make_result([pair1, pair2])
        report = run_grounding_checks(result)

        flagged = [r for r in report.redundancy_checks if r.flagged]
        assert len(flagged) == 0, f"Expected no redundancy flags, got: {flagged}"


