class TestThresholdTuning:
    """Tests to help tune checker thresholds."""

    def test_token_overlap_calculation(self):
        """Verify token overlap behaves as expected."""
        # High overlap case
        sentence = "reads from or writes to memory location outside boundary"
        quote = "reads from or writes to a memory location outside the buffer's intended boundary"

        sent_tokens = content_tokens(sentence)
        quote_tokens = content_tokens(quote)
        overlap = overlap_ratio(sent_tokens, quote_tokens)

        # Should have high overlap since most sentence tokens are in quote
        assert overlap > 0.7, f"Expected high overlap, got {overlap}"

    def test_jaccard_similarity_calculation(self):
        """Verify Jaccard similarity behaves as expected."""
        set_a = {"memory", "buffer", "operations", "read", "write"}
        set_b = {"memory", "buffer", "boundary", "overflow"}

        sim = jaccard_similarity(set_a, set_b)
        # Intersection: memory, buffer (2)
        # Union: memory, buffer, operations, read, write, boundary, overflow (7)
        # Jaccard = 2/7 ≈ 0.286
        assert 0.25 < sim < 0.35, f"Expected ~0.286, got {sim}"

    def test_relaxed_config_passes_borderline(self):
        """A relaxed config should pass borderline cases."""
        relaxed = CheckerConfig(
            min_sentence_token_overlap=0.30,  # Lower than default 0.45
            min_sentence_quote_jaccard=0.15,   # Lower than default 0.20
        )

        pair = make_pair(
            pair_id="CWE-119-QRA-1",
            pair_type="risk_context",
            question="What are the consequences of CWE-119?",
            # Reasoning has some overlap but introduces synthesis
            reasoning="Memory operations outside intended boundaries can corrupt data and crash systems.",
            answer="Out-of-bounds memory access leads to crashes and data corruption.",
            evidence=[
                {"field": "description", "quote": "memory location outside the buffer's intended boundary"},
                {"field": "common_consequences", "quote": "corruption of relevant memory, possibly leading to a crash"},
            ],
        )
        result = make_result([pair])

        # Default config might fail
        default_report = run_grounding_checks(result)

        # Relaxed config should pass
        relaxed_report = run_grounding_checks(result, config=relaxed)

        # At minimum, relaxed should have fewer failures
        default_unsupported = sum(
            1 for c in default_report.pair_checks[0].reasoning_checks + default_report.pair_checks[0].answer_checks
            if not c.supported
        )
        relaxed_unsupported = sum(
            1 for c in relaxed_report.pair_checks[0].reasoning_checks + relaxed_report.pair_checks[0].answer_checks
            if not c.supported
        )

        assert relaxed_unsupported <= default_unsupported, "Relaxed config should not be stricter"


